#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/timing/timing.h> // For precise timing measurements

/* Test configuration defines */
#define TEST_TIMEOUT_MS         100
#define TEST_PERIOD_MS          50
#define BUSY_WAIT_DURATION_US   1000 // 1ms
#define TIMER_USER_DATA_VALUE   0xDEADBEEF

/* Global timer instance and related variables */
static struct k_timer test_timer;
static volatile int timer_expiry_count;
static volatile k_timeout_t timer_last_remaining;
static void *timer_user_data_ptr;

/* Timer expiry handler function */
void timer_expiry_handler(struct k_timer *timer)
{
    ARG_UNUSED(timer);
    timer_expiry_count++;
    timer_last_remaining = k_timer_remaining_get(&test_timer);
    timer_user_data_ptr = k_timer_user_data_get(&test_timer);
}

/* Define a static timer with an expiry handler */
K_TIMER_DEFINE(static_timer, timer_expiry_handler, NULL);

/* Ztest suite setup */
ZTEST_SUITE(timer_api_tests, NULL, NULL, NULL, NULL, NULL);

/* Test case 1: Basic timer start/stop and one-shot expiry */
ZTEST(timer_api_tests, test_timer_basic_start_stop)
{
    timer_expiry_count = 0;
    k_timer_init(&test_timer, timer_expiry_handler, NULL);

    /* Start a one-shot timer */
    k_timer_start(&test_timer, K_MSEC(TEST_TIMEOUT_MS), K_NO_WAIT);
    zassert_true(k_timer_is_active(&test_timer), "Timer should be active immediately after start");

    /* Wait for the timer to expire */
    k_sleep(K_MSEC(TEST_TIMEOUT_MS + 20)); // Add some buffer time
    zassert_equal(timer_expiry_count, 1, "Timer should have expired exactly once");
    zassert_false(k_timer_is_active(&test_timer), "One-shot timer should not be active after expiry");

    /* Test stopping an active timer before it expires */
    timer_expiry_count = 0;
    k_timer_start(&test_timer, K_MSEC(TEST_TIMEOUT_MS * 2), K_MSEC(TEST_PERIOD_MS)); // Start a periodic timer
    zassert_true(k_timer_is_active(&test_timer), "Timer should be active for periodic test");
    k_sleep(K_MSEC(TEST_TIMEOUT_MS / 2)); // Wait for half the initial timeout
    k_timer_stop(&test_timer);
    zassert_false(k_timer_is_active(&test_timer), "Timer should be stopped by k_timer_stop()");
    zassert_equal(timer_expiry_count, 0, "Timer should not have expired if stopped early");
}

/* Test case 2: Periodic timer functionality */
ZTEST(timer_api_tests, test_timer_periodic)
{
    timer_expiry_count = 0;
    k_timer_init(&test_timer, timer_expiry_handler, NULL);

    /* Start a periodic timer */
    k_timer_start(&test_timer, K_MSEC(TEST_TIMEOUT_MS), K_MSEC(TEST_PERIOD_MS));
    /* Wait for initial expiry + a few periods */
    k_sleep(K_MSEC(TEST_TIMEOUT_MS + (TEST_PERIOD_MS * 3) + 20));
    k_timer_stop(&test_timer);
    /* Expect initial expiry + 3 periodic expiries */
    zassert_equal(timer_expiry_count, 1 + 3, "Periodic timer should have expired initial + 3 times");
}

/* Test case 3: k_timer_remaining_get and k_timer_expires_get */
ZTEST(timer_api_tests, test_timer_remaining_expires)
{
    k_timer_init(&test_timer, NULL, NULL); // No expiry handler needed for this test

    /* Start a timer and check its remaining and expires values */
    k_timer_start(&test_timer, K_MSEC(TEST_TIMEOUT_MS), K_NO_WAIT);

    k_timeout_t remaining = k_timer_remaining_get(&test_timer);
    zassert_true(k_timeout_to_ms_floor32(remaining) <= TEST_TIMEOUT_MS, "Remaining time should be <= initial timeout");
    zassert_true(k_timeout_to_ms_floor32(remaining) > 0, "Remaining time should be > 0 when active");

    k_timeout_t expires = k_timer_expires_get(&test_timer);
    zassert_true(k_timeout_to_ms_floor32(expires) == TEST_TIMEOUT_MS, "Expires time should match initial timeout");

    /* Wait for some time and check again */
    k_sleep(K_MSEC(TEST_TIMEOUT_MS / 2));
    remaining = k_timer_remaining_get(&test_timer);
    zassert_true(k_timeout_to_ms_floor32(remaining) <= TEST_TIMEOUT_MS / 2, "Remaining time should have decreased");
    zassert_true(k_timeout_to_ms_floor32(remaining) > 0, "Remaining time should still be > 0");

    k_timer_stop(&test_timer);
    remaining = k_timer_remaining_get(&test_timer);
    zassert_true(K_TIMEOUT_EQ(remaining, K_NO_WAIT), "Remaining time should be K_NO_WAIT after stop");
}

/* Test case 4: k_timer_status_get functionality */
ZTEST(timer_api_tests, test_timer_status_get)
{
    k_timer_init(&test_timer, NULL, NULL);
    int status;

    /* Test one-shot timer status */
    k_timer_start(&test_timer, K_MSEC(TEST_TIMEOUT_MS), K_NO_WAIT);
    status = k_timer_status_get(&test_timer);
    zassert_equal(status, 0, "Status should be 0 before one-shot expiry");
    k_sleep(K_MSEC(TEST_TIMEOUT_MS + 20));
    status = k_timer_status_get(&test_timer);
    zassert_equal(status, 1, "Status should be 1 after one-shot expiry");

    /* Test periodic timer status */
    k_timer_start(&test_timer, K_MSEC(TEST_TIMEOUT_MS), K_MSEC(TEST_PERIOD_MS));
    k_sleep(K_MSEC(TEST_TIMEOUT_MS + (TEST_PERIOD_MS * 2) + 20));
    status = k_timer_status_get(&test_timer);
    /* Expect initial expiry + 2 periodic expiries */
    zassert_equal(status, 1 + 2, "Status should reflect initial + 2 periodic expiries");
    k_timer_stop(&test_timer);
}

/* Test case 5: k_busy_wait duration accuracy */
ZTEST(timer_api_tests, test_busy_wait_duration)
{
    timing_t start_time, end_time;
    uint64_t duration_us;

    /* Initialize and start the timing infrastructure */
    timing_init();
    timing_start();

    /* Record start time */
    start_time = timing_counter_get();

    /* Perform the busy wait. This is the line with the typo. */
    // The error was 'k_busy_wiat', corrected to 'k_busy_wait'.
    k_busy_wait(BUSY_WAIT_DURATION_US);

    /* Record end time */
    end_time = timing_counter_get();

    /* Stop timing and calculate duration */
    timing_stop();
    duration_us = timing_cycles_to_us(end_time - start_time);

    /* Assert that the busy wait duration is within an acceptable range */
    /* Allowing for +/- 20% tolerance due to scheduling and clock precision */
    zassert_true(duration_us >= (BUSY_WAIT_DURATION_US * 8) / 10,
                 "Busy wait duration too short: %llu us (expected ~%d us)",
                 duration_us, BUSY_WAIT_DURATION_US);
    zassert_true(duration_us <= (BUSY_WAIT_DURATION_US * 12) / 10,
                 "Busy wait duration too long: %llu us (expected ~%d us)",
                 duration_us, BUSY_WAIT_DURATION_US);
}

/* Test case 6: k_timer_user_data_set/get */
ZTEST(timer_api_tests, test_timer_user_data)
{
    int my_data = TIMER_USER_DATA_VALUE;
    k_timer_init(&test_timer, timer_expiry_handler, NULL); // Use handler to check data on expiry
    k_timer_user_data_set(&test_timer, &my_data);

    /* Check immediately */
    void *retrieved_data = k_timer_user_data_get(&test_timer);
    zassert_equal(retrieved_data, &my_data, "User data not correctly retrieved immediately");

    /* Check after expiry */
    timer_user_data_ptr = NULL; // Clear before expiry
    k_timer_start(&test_timer, K_MSEC(10), K_NO_WAIT);
    k_sleep(K_MSEC(20));
    zassert_equal(timer_user_data_ptr, &my_data, "User data not correctly retrieved in expiry handler");
    k_timer_stop(&test_timer);
}

/* Test case 7: k_timer_remaining_get and k_timer_expires_get after timer expiry */
ZTEST(timer_api_tests, test_timer_post_expiry_state)
{
    k_timer_init(&test_timer, NULL, NULL);
    k_timer_start(&test_timer, K_MSEC(10), K_NO_WAIT);
    k_sleep(K_MSEC(20)); // Ensure timer has expired

    k_timeout_t remaining = k_timer_remaining_get(&test_timer);
    zassert_true(K_TIMEOUT_EQ(remaining, K_NO_WAIT), "Remaining time should be K_NO_WAIT after expiry");

    k_timeout_t expires = k_timer_expires_get(&test_timer);
    zassert_true(K_TIMEOUT_EQ(expires, K_NO_WAIT), "Expires time should be K_NO_WAIT after expiry");
}

/* Test case 8: k_timer_status_get after timer expiry and stop */
ZTEST(timer_api_tests, test_timer_status_post_expiry_stop)
{
    k_timer_init(&test_timer, NULL, NULL);
    k_timer_start(&test_timer, K_MSEC(10), K_NO_WAIT);
    k_sleep(K_MSEC(20)); // Ensure timer has expired
    int status = k_timer_status_get(&test_timer);
    zassert_equal(status, 1, "Status should be 1 after one-shot expiry");
    k_timer_stop(&test_timer); // Stop it explicitly
    status = k_timer_status_get(&test_timer);
    zassert_equal(status, 0, "Status should be 0 after stop, even if expired");
}
